src/deployment/DeployBurnMintTokenPool.s.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {Script, console} from "forge-std/Script.sol";
import {HelperUtils} from "../utils/HelperUtils.s.sol";
import {HelperConfig} from "../HelperConfig.s.sol";
import {ChainNameResolver} from "../utils/ChainNameResolver.s.sol";
import {BurnMintTokenPool} from "@chainlink/contracts-ccip/contracts/pools/BurnMintTokenPool.sol";
import {rwaUSD} from "@rwausd/src/token/RWAUSD.sol";
import {IBurnMintERC20} from "@chainlink/contracts/src/v0.8/shared/token/ERC20/IBurnMintERC20.sol";

contract DeployBurnMintTokenPool is Script {
    address public pool;

    function _deploy(string memory chainName) internal {
        string memory root = vm.projectRoot();
        string memory deployedTokenPath = string.concat(root, "/src/output/deployedToken_", chainName, ".json");

        address tokenAddress =
            HelperUtils.getAddressFromJson(vm, deployedTokenPath, string.concat(".deployedToken_", chainName));

        HelperConfig helperConfig = new HelperConfig();
        (, address router, address rmnProxy,,,,,) = helperConfig.activeNetworkConfig();

        require(tokenAddress != address(0), "Invalid token address");
        require(router != address(0) && rmnProxy != address(0), "Router or RMN Proxy not defined for this network");

        BurnMintTokenPool tokenPool =
            new BurnMintTokenPool(IBurnMintERC20(tokenAddress), 18, new address[](0), rmnProxy, router);

        console.log("Burn & Mint token pool deployed to:", address(tokenPool));

        rwaUSD(tokenAddress).grantMintAndBurnRoles(address(tokenPool));
        console.log("Granted mint and burn roles to token pool:", address(tokenPool));

        pool = address(tokenPool);

        string memory jsonObj = "deployedTokenPool";
        string memory key = string(abi.encodePacked("deployedTokenPool_", chainName));
        string memory finalJson = vm.serializeAddress(jsonObj, key, address(tokenPool));
        string memory poolFileName = string.concat(root, "/src/output/deployedTokenPool_", chainName, ".json");
        console.log("Writing deployed token pool address to file:", poolFileName);
        vm.writeJson(finalJson, poolFileName);
    }

    function run() external {
        string memory chainName = new ChainNameResolver().getChainNameSafe(block.chainid);

        bool isTest = vm.envOr("IS_TEST", false);
        if (isTest) {
            address admin = HelperUtils.getAddressFromJson(
                vm,
                vm.envOr("CONFIG_PATH", string.concat(vm.projectRoot(), "/src/mainnet.config.json")),
                ".rwaUSDToken.ccipAdminAddress"
            );
            vm.startPrank(admin);
        } else {
            vm.startBroadcast();
        }

        _deploy(chainName);

        if (isTest) {
            vm.stopPrank();
        } else {
            vm.stopBroadcast();
        }
    }

    function runWithPrankedAdmin() external {
        string memory chainName = new ChainNameResolver().getChainNameSafe(block.chainid);
        string memory configPath = vm.envOr("CONFIG_PATH", string.concat(vm.projectRoot(), "/src/mainnet.config.json"));
        address admin = HelperUtils.getAddressFromJson(vm, configPath, ".rwaUSDToken.ccipAdminAddress");
        vm.startPrank(admin);
        _deploy(chainName);
        vm.stopPrank();
    }
}

src/deployment/DeployToken.s.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {Script, console} from "forge-std/Script.sol";
import {HelperUtils} from "../utils/HelperUtils.s.sol";
import {ChainNameResolver} from "../utils/ChainNameResolver.s.sol";
import {rwaUSD} from "@rwausd/src/token/RWAUSD.sol";
import {Upgrades} from "openzeppelin-foundry-upgrades/Upgrades.sol";

contract DeployToken is Script {
    address public proxy;
    address public implementation;

    function run() external {
        ChainNameResolver resolver = new ChainNameResolver();
        string memory chainName = resolver.getChainNameSafe(block.chainid);

        string memory root = vm.projectRoot();
        string memory configPath = vm.envOr("CONFIG_PATH", string.concat(root, "/src/mainnet.config.json"));

        address admin = HelperUtils.getAddressFromJson(vm, configPath, ".rwaUSDToken.ccipAdminAddress");
        string memory name = HelperUtils.getStringFromJson(vm, configPath, ".rwaUSDToken.name");
        string memory symbol = HelperUtils.getStringFromJson(vm, configPath, ".rwaUSDToken.symbol");
        uint256 decimals = HelperUtils.getUintFromJson(vm, configPath, ".rwaUSDToken.decimals");

        bool isTest = vm.envOr("IS_TEST", false);
        if (isTest) {
            vm.startPrank(admin);
        } else {
            vm.startBroadcast();
        }

        bytes memory data = abi.encodeCall(
            rwaUSD.initialize,
            (
                name,
                symbol,
                uint8(decimals),
                0, // maxSupply (unlimited)
                0, // preMint
                admin,
                admin // defaultUpgrader
            )
        );
        proxy = Upgrades.deployUUPSProxy("RWAUSD.sol:rwaUSD", data);

        // Fetch implementation address
        bytes32 implSlot = bytes32(uint256(keccak256("eip1967.proxy.implementation")) - 1);
        implementation = address(uint160(uint256(vm.load(proxy, implSlot))));

        console.log("Deployed rwaUSD proxy at:", proxy);
        console.log("Deployed rwaUSD implementation at:", implementation);
        console.log("Admin:", admin);

        if (isTest) {
            vm.stopPrank();
        } else {
            vm.stopBroadcast();
        }

        string memory jsonObj = "deployedToken";
        string memory key = string(abi.encodePacked("deployedToken_", chainName));
        string memory finalJson = vm.serializeAddress(jsonObj, key, proxy);
        string memory fileName = string(abi.encodePacked("./src/output/deployedToken_", chainName, ".json"));
        console.log("Writing deployed token address to file:", fileName);
        vm.writeJson(finalJson, fileName);
    }
}

src/maintenance/1_ClaimAdminAndAcceptAdm.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {Script, console} from "forge-std/Script.sol";
import {HelperUtils} from "../utils/HelperUtils.s.sol";
import {HelperConfig} from "../HelperConfig.s.sol";
import {ChainNameResolver} from "../utils/ChainNameResolver.s.sol";
import {
    RegistryModuleOwnerCustom
} from "@chainlink/contracts-ccip/contracts/tokenAdminRegistry/RegistryModuleOwnerCustom.sol";
import {TokenAdminRegistry} from "@chainlink/contracts-ccip/contracts/tokenAdminRegistry/TokenAdminRegistry.sol";
import {rwaUSD} from "@rwausd/src/token/RWAUSD.sol";

contract ClaimAdminAndAcceptAdmin is Script {
    address internal constant TOKEN_ADMIN = 0x194Ebc1B9B382ef0E6998cAAcE59aF843cf53b99; // Multipli Safe Wallet

    struct ClaimAdminConfig {
        address tokenAddress;
        address registryModuleOwnerCustom;
        address tokenAdminRegistry;
        address tokenAdmin;
    }

    function run() external {
        _runInternal(false, address(0));
    }

    function runWithPrankedUser(address user) external {
        _runInternal(true, user);
    }

    function _runInternal(bool usePrank, address user) internal {
        ClaimAdminConfig memory config = loadConfig();
        _validateConfig(config);

        bytes memory callData1 = _buildClaimAdminCalldata(config.tokenAddress);
        bytes memory callData2 = _buildAcceptAdminRoleCalldata(config.tokenAddress);

        _logSafeTransaction(config.registryModuleOwnerCustom, callData1, config.tokenAdminRegistry, callData2);

        if (usePrank) {
            vm.startPrank(user);
            _execute(config.registryModuleOwnerCustom, callData1, config.tokenAdminRegistry, callData2);
            vm.stopPrank();
        }
    }

    function loadConfig() public returns (ClaimAdminConfig memory config) {
        config.tokenAdmin = TOKEN_ADMIN;
        config.tokenAddress = _loadTokenAddress();
        config.registryModuleOwnerCustom = _loadRegistryModuleOwnerCustom();
        config.tokenAdminRegistry = _loadTokenAdminRegistry();
    }

    function _loadTokenAddress() internal returns (address tokenAddress) {
        ChainNameResolver resolver = new ChainNameResolver();
        string memory chainName = resolver.getChainNameSafe(block.chainid);

        string memory root = vm.projectRoot();
        string memory deployedTokenPath = string.concat(root, "/src/output/deployedToken_", chainName, ".json");

        tokenAddress =
            HelperUtils.getAddressFromJson(vm, deployedTokenPath, string.concat(".deployedToken_", chainName));
    }

    function _loadRegistryModuleOwnerCustom() internal returns (address registryModuleOwnerCustom) {
        HelperConfig helperConfig = new HelperConfig();
        (,,,, registryModuleOwnerCustom,,,) = helperConfig.activeNetworkConfig();
    }

    function _loadTokenAdminRegistry() internal returns (address tokenAdminRegistry) {
        HelperConfig helperConfig = new HelperConfig();
        (,,, tokenAdminRegistry,,,,) = helperConfig.activeNetworkConfig();
    }

    function _validateConfig(ClaimAdminConfig memory config) internal view {
        require(config.tokenAddress != address(0), "Invalid token address");
        require(
            config.registryModuleOwnerCustom != address(0),
            "Registry module owner custom is not defined for this network"
        );

        require(config.tokenAdminRegistry != address(0), "Token Admin Registry is not defined for this network");

        address currentCCIPAdmin = rwaUSD(config.tokenAddress).getCCIPAdmin();
        console.log("Current token admin:", currentCCIPAdmin);

        require(currentCCIPAdmin == config.tokenAdmin, "CCIP admin of token doesn't match the token admin address");
    }

    function _buildClaimAdminCalldata(address tokenAddress) internal pure returns (bytes memory) {
        return abi.encodeWithSelector(RegistryModuleOwnerCustom.registerAdminViaGetCCIPAdmin.selector, tokenAddress);
    }

    function _buildAcceptAdminRoleCalldata(address tokenAddress) internal pure returns (bytes memory) {
        return abi.encodeWithSelector(TokenAdminRegistry.acceptAdminRole.selector, tokenAddress);
    }

    function _logSafeTransaction(
        address registryModuleOwnerCustom,
        bytes memory cd1,
        address tokenAdminRegistry,
        bytes memory cd2
    ) internal view {
        console.log("=== Safe Wallet Transaction 1 ===");
        console.log("To (registryModuleOwnerCustom):", registryModuleOwnerCustom);
        console.log("Value: 0");
        console.log("Calldata:");
        console.logBytes(cd1);
        console.log("===============================");

        console.log("=== Safe Wallet Transaction 2 ===");
        console.log("To (tokenAdminRegistry):", tokenAdminRegistry);
        console.log("Value: 0");
        console.log("Calldata:");
        console.logBytes(cd2);
        console.log("===============================");
    }

    function _execute(
        address registryModuleOwnerCustom,
        bytes memory callData1,
        address tokenAdminRegistry,
        bytes memory callData2
    ) internal {
        (bool success,) = registryModuleOwnerCustom.call(callData1);
        require(success, "error executing calldata1");

        (success,) = tokenAdminRegistry.call(callData2);
        require(success, "error executing calldata2");
    }
}

