// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {Script, console} from "forge-std/Script.sol";
import {HelperUtils} from "../utils/HelperUtils.s.sol";
import {ChainNameResolver} from "../utils/ChainNameResolver.s.sol";
import {Upgrades, Options} from "openzeppelin-foundry-upgrades/Upgrades.sol";
import {rwaUSD} from "@rwausd/src/token/RWAUSD.sol";

contract UpgradeToken is Script {
    address public lastImplAddress;

    struct UpgradeConfig {
        address proxyAddress;
        address upgrader;
    }

    function run() external {
        UpgradeConfig memory config = loadConfig();
        _validateConfig(config);

        Upgrades.validateUpgrade("rwaUSD.sol:rwaUSD", _opts());

        string memory versionTag = vm.envString("RWAUSD_VERSION");
        require(bytes(versionTag).length > 0, "RWAUSD_VERSION must not be empty");
        lastImplAddress = computeImplAddress(versionTag);

        bytes32 salt = keccak256(abi.encode("RWAUSD_UPGRADE", versionTag));
        bytes memory creationCode = type(rwaUSD).creationCode;

        console.log("=== Tx 1: Deploy implementation ===");
        console.log("To:", CREATE2_FACTORY);
        console.logBytes(abi.encodePacked(salt, creationCode));

        console.log("=== Tx 2: Upgrade proxy ===");
        console.log("To:", config.proxyAddress);
        console.log("Submit from Safe:", config.upgrader);
        console.logBytes(
            abi.encodeWithSelector(bytes4(keccak256("upgradeToAndCall(address,bytes)")), lastImplAddress, bytes(""))
        );
    }

    function runWithPrankedUser(address user) external {
        UpgradeConfig memory config = loadConfig();
        _validateConfig(config);
        vm.startPrank(user);
        _run(config.proxyAddress);
        vm.stopPrank();
    }

    function _run(address proxyAddress) internal {
        Upgrades.upgradeProxy(proxyAddress, "rwaUSD.sol:rwaUSD", bytes(""), _opts());
    }

    function computeImplAddress(string memory versionTag) public view returns (address) {
        bytes32 salt = keccak256(abi.encode("RWAUSD_UPGRADE", versionTag));
        bytes memory creationCode = type(rwaUSD).creationCode;
        return address(
            uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), CREATE2_FACTORY, salt, keccak256(creationCode)))))
        );
    }

    function _opts() internal pure returns (Options memory opts) {
        opts.referenceBuildInfoDir = "build-info/build-info-v1";
        opts.referenceContract = "build-info-v1:rwaUSD";
    }

    function loadConfig() public returns (UpgradeConfig memory config) {
        ChainNameResolver resolver = new ChainNameResolver();
        string memory chainName = resolver.getChainNameSafe(block.chainid);

        string memory root = vm.projectRoot();
        string memory configPath = vm.envOr("CONFIG_PATH", string.concat(root, "/src/mainnet.config.json"));
        string memory localTokenPath = string.concat(root, "/src/output/deployedToken_", chainName, ".json");

        config.proxyAddress =
            HelperUtils.getAddressFromJson(vm, localTokenPath, string.concat(".deployedToken_", chainName));
        config.upgrader = HelperUtils.getAddressFromJson(vm, configPath, ".rwaUSDToken.upgraderAddress");
    }

    function _validateConfig(UpgradeConfig memory config) internal pure {
        require(config.proxyAddress != address(0), "Invalid proxy address");
        require(config.upgrader != address(0), "Invalid upgrader address");
    }
}

// forge clean && forge build
// RWAUSD_VERSION=1.0.0 forge script ./src/maintenance/3_UpgradeToken.s.sol:UpgradeToken --rpc-url eth_mainnet
// Submit both logged calldatas as a batched Safe transaction from UPGRADER_ROLE wallet (0x194Ebc1B9B382ef0E6998cAAcE59aF843cf53b99)

