// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {Test, console} from "forge-std/Test.sol";
import {Script} from "forge-std/Script.sol";
import {DeployToken} from "src/deployment/DeployToken.s.sol";
import {HelperUtils} from "src/utils/HelperUtils.s.sol";
import {rwaUSD} from "@rwausd/src/token/RWAUSD.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

contract TestDeployToken is Test {
    address internal ADMIN; // ccipAdminAddress from config
    address internal DEPLOYER = makeAddr("deployer"); // arbitrary tx sender

    string internal configPath;
    string internal chainName = "anvil"; // adjust if ChainNameResolver returns something else
    string internal outputPath;

    function setUp() public {
        configPath = string.concat(vm.projectRoot(), "/src/mainnet.config.json");
        outputPath = string.concat(vm.projectRoot(), "/src/output/deployedToken_", chainName, ".json");

        vm.setEnv("CONFIG_PATH", configPath);
        vm.setEnv("IS_TEST", "true");

        ADMIN = HelperUtils.getAddressFromJson(vm, configPath, ".rwaUSDToken.ccipAdminAddress");
    }

    /// Deploy via the script and return both proxy and implementation.
    function _runDeploy() internal returns (address proxy, address implementation) {
        DeployToken deployer = new DeployToken();

        vm.startPrank(DEPLOYER);
        deployer.run();
        vm.stopPrank();

        proxy = deployer.proxy();
        implementation = deployer.implementation();
    }

    function test_DeployProxyIsContract() public {
        (address proxy,) = _runDeploy();
        assertTrue(proxy != address(0), "proxy address is zero");
        assertTrue(proxy.code.length > 0, "proxy has no code");
    }

    function test_TokenMetadata() public {
        (address proxy,) = _runDeploy();
        rwaUSD token = rwaUSD(proxy);

        string memory expectedName = HelperUtils.getStringFromJson(vm, configPath, ".rwaUSDToken.name");
        string memory expectedSymbol = HelperUtils.getStringFromJson(vm, configPath, ".rwaUSDToken.symbol");
        uint256 expectedDecimals = HelperUtils.getUintFromJson(vm, configPath, ".rwaUSDToken.decimals");

        assertEq(token.name(), expectedName, "name mismatch");
        assertEq(token.symbol(), expectedSymbol, "symbol mismatch");
        assertEq(token.decimals(), uint8(expectedDecimals), "decimals mismatch");
    }

    function test_TotalSupplyIsZeroAfterDeploy() public {
        (address proxy,) = _runDeploy();
        assertEq(rwaUSD(proxy).totalSupply(), 0, "pre-mint should be 0");
    }

    function test_AdminAddressIsCorrect() public {
        address expectedAdmin = 0x8cFee31bf3A57EC2C86D9e0f476Bd36aCA611Fa5;
        assertEq(ADMIN, expectedAdmin, "ADMIN address mismatch with config");
    }

    function test_AdminHasAdminRole() public {
        (address proxy,) = _runDeploy();
        rwaUSD token = rwaUSD(proxy);

        assertTrue(token.hasRole(token.DEFAULT_ADMIN_ROLE(), ADMIN), "admin missing DEFAULT_ADMIN_ROLE");
    }

    function test_AdminHasUpgraderRole() public {
        (address proxy,) = _runDeploy();
        rwaUSD token = rwaUSD(proxy);

        assertTrue(token.hasRole(token.UPGRADER_ROLE(), ADMIN), "admin missing UPGRADER_ROLE");
    }

    function test_ProxyPointsToImplementation() public {
        (address proxy, address expectedImpl) = _runDeploy();

        bytes32 implSlot = bytes32(uint256(keccak256("eip1967.proxy.implementation")) - 1);
        address impl = address(uint160(uint256(vm.load(proxy, implSlot))));

        assertTrue(impl != address(0), "implementation slot is zero");
        assertEq(impl, expectedImpl, "implementation mismatch");
        assertTrue(impl.code.length > 0, "implementation has no code");
        assertTrue(proxy != impl, "proxy should not equal implementation");
    }

    function test_NonUpgraderCannotUpgrade() public {
        (address proxy,) = _runDeploy();
        address attacker = makeAddr("attacker");
        address newImpl = address(new rwaUSD());

        vm.prank(attacker);
        vm.expectRevert();
        UUPSUpgradeable(proxy).upgradeToAndCall(newImpl, "");
    }

    function test_AdminCanUpgradeToNewImpl() public {
        (address proxy,) = _runDeploy();
        address newImpl = address(new rwaUSD());

        vm.prank(ADMIN);
        UUPSUpgradeable(proxy).upgradeToAndCall(newImpl, "");

        bytes32 implSlot = bytes32(uint256(keccak256("eip1967.proxy.implementation")) - 1);
        address storedImpl = address(uint160(uint256(vm.load(proxy, implSlot))));

        assertEq(storedImpl, newImpl, "implementation not updated");
    }

    function test_CannotReinitialize() public {
        (address proxy,) = _runDeploy();

        vm.expectRevert();
        rwaUSD(proxy).initialize("Hack", "HCK", 18, 0, 0, address(this), address(this));
    }

    function test_OutputFileWritten() public {
        (address proxy,) = _runDeploy();

        address stored = vm.parseJsonAddress(vm.readFile(outputPath), string.concat(".deployedToken_", chainName));

        assertEq(stored, proxy, "output JSON address mismatch");
    }
}

