// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {Test, console} from "forge-std/Test.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC165} from "@openzeppelin/contracts/utils/introspection/IERC165.sol";
import {IAccessControl} from "@openzeppelin/contracts/access/IAccessControl.sol";
import {
    IAccessControlDefaultAdminRules
} from "@openzeppelin/contracts/access/extensions/IAccessControlDefaultAdminRules.sol";
import {IERC1822Proxiable} from "@openzeppelin/contracts/interfaces/draft-IERC1822.sol";
import {UpgradeToken} from "src/maintenance/3_UpgradeToken.s.sol";
import {rwaUSD} from "@rwausd/src/token/RWAUSD.sol";
import {IBurnMintERC20} from "@rwausd/src/interfaces/IBurnMintERC20.sol";
import {IGetCCIPAdmin} from "@chainlink/contracts/src/v0.8/shared/interfaces/IGetCCIPAdmin.sol";
contract TestUpgradeToken is Test {
    uint256 constant BLOCK_NUMBER = 25_129_133;

    UpgradeToken script;

    address internal constant PROXY = 0x8Fcd23142047A3073ed332a0Ed07d1e8D2BD5177;
    address internal constant UPGRADER = 0x194Ebc1B9B382ef0E6998cAAcE59aF843cf53b99; // Multipli Safe Wallet (DEFAULT_ADMIN)

    bytes32 internal constant IMPL_SLOT = bytes32(uint256(keccak256("eip1967.proxy.implementation")) - 1);

    bytes32 internal constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 internal constant BURNER_ROLE = keccak256("BURNER_ROLE");
    bytes32 internal constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    address internal minter;
    address internal burner;
    address internal pauser;
    address internal alice;
    address internal bob;
    address internal spender;

    uint256 internal constant TEST_AMOUNT = 1_000e18;

    uint256 private initialStateSnapshot;
    bool private initialStateSetup;

    struct TokenState {
        // ERC20 basics
        string name;
        string symbol;
        uint8 decimals;
        uint256 totalSupply;
        uint256 maxSupply;
        // rwaUSD-specific
        address ccipAdmin;
        bool paused;
        // Per-user
        uint256 userBalance;
        uint256 userAllowanceToSpender;
        // supportsInterface
        bool supportsIERC20;
        bool supportsIBurnMintERC20;
        bool supportsIGetCCIPAdmin;
        bool supportsIERC1822;
        bool supportsIERC165;
        bool supportsIAccessControl;
        bool supportsIAccessControlDefaultAdminRules;
    }

    TokenState internal stateBefore;
    TokenState internal stateAfterUpgrade;

    function setUp() public {
        string memory rpcUrl = vm.envOr("RPC_URL_ETHEREUM_MAINNET", string("https://eth.drpc.org"));
        vm.createSelectFork(rpcUrl, BLOCK_NUMBER);

        script = new UpgradeToken();

        minter = makeAddr("minter");
        burner = makeAddr("burner");
        pauser = makeAddr("pauser");
        alice = makeAddr("alice");
        bob = makeAddr("bob");
        spender = makeAddr("spender");
    }

    function _getImplementation(address proxy) internal view returns (address) {
        return address(uint160(uint256(vm.load(proxy, IMPL_SLOT))));
    }

    function _upgradeContract() internal {
        script.runWithPrankedUser(UPGRADER);
    }

    function _setupInitialState() internal {
        if (initialStateSetup) return;

        vm.startPrank(UPGRADER);
        rwaUSD(PROXY).grantRole(MINTER_ROLE, minter);
        rwaUSD(PROXY).grantRole(BURNER_ROLE, burner);
        rwaUSD(PROXY).grantRole(PAUSER_ROLE, pauser);
        vm.stopPrank();

        vm.startPrank(minter);
        rwaUSD(PROXY).mint(alice, TEST_AMOUNT * 10);
        rwaUSD(PROXY).mint(bob, TEST_AMOUNT * 5);
        rwaUSD(PROXY).mint(spender, TEST_AMOUNT * 3);
        vm.stopPrank();

        // alice approves spender for regular (non-max) allowance
        vm.prank(alice);
        rwaUSD(PROXY).approve(spender, TEST_AMOUNT);

        initialStateSnapshot = vm.snapshot();
        initialStateSetup = true;
    }

    function _restoreInitialState() internal {
        vm.revertTo(initialStateSnapshot);
    }

    function _captureState(address user) internal view returns (TokenState memory s) {
        rwaUSD token = rwaUSD(PROXY);
        s = TokenState({
            name: token.name(),
            symbol: token.symbol(),
            decimals: token.decimals(),
            totalSupply: token.totalSupply(),
            maxSupply: token.maxSupply(),
            ccipAdmin: token.getCCIPAdmin(),
            paused: token.paused(),
            userBalance: token.balanceOf(user),
            userAllowanceToSpender: token.allowance(user, spender),
            supportsIERC20: token.supportsInterface(type(IERC20).interfaceId),
            supportsIBurnMintERC20: token.supportsInterface(type(IBurnMintERC20).interfaceId),
            supportsIGetCCIPAdmin: token.supportsInterface(type(IGetCCIPAdmin).interfaceId),
            supportsIERC1822: token.supportsInterface(type(IERC1822Proxiable).interfaceId),
            supportsIERC165: token.supportsInterface(type(IERC165).interfaceId),
            supportsIAccessControl: token.supportsInterface(type(IAccessControl).interfaceId),
            supportsIAccessControlDefaultAdminRules: token.supportsInterface(
                type(IAccessControlDefaultAdminRules).interfaceId
            )
        });
    }

    // ============================================================
    // Sanity checks
    // ============================================================

    function test_sanityCheckForVariables() public {
        UpgradeToken.UpgradeConfig memory config = script.loadConfig();

        assertEq(config.proxyAddress, PROXY, "proxy address mismatch");
        assertEq(config.upgrader, UPGRADER, "upgrader address mismatch");
    }

    // ============================================================
    // Version-tagged calldata
    // ============================================================

    function test_run_RevertWhen_VersionNotSet() public {
        vm.setEnv("RWAUSD_VERSION", ""); // clear any value set by prior tests
        vm.expectRevert();
        script.run();
    }

    function test_run_DifferentVersions_ProduceDifferentAddresses() public view {
        bytes32 salt1 = keccak256(abi.encode("RWAUSD_UPGRADE", "1.0.0"));
        bytes32 salt2 = keccak256(abi.encode("RWAUSD_UPGRADE", "2.0.0"));
        bytes memory creationCode = type(rwaUSD).creationCode;
        bytes32 initCodeHash = keccak256(creationCode);

        address impl1 =
            address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), CREATE2_FACTORY, salt1, initCodeHash)))));
        address impl2 =
            address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), CREATE2_FACTORY, salt2, initCodeHash)))));

        assertTrue(impl1 != impl2, "different versions must produce different addresses");
        assertEq(
            impl1,
            address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff), CREATE2_FACTORY, salt1, initCodeHash))))),
            "same version must produce same address"
        );
    }

    function test_run_WithVersionSet_Succeeds() public {
        vm.setEnv("RWAUSD_VERSION", "1.0.0");
        script.run();

        address expectedImpl = script.computeImplAddress("1.0.0");
        assertEq(script.lastImplAddress(), expectedImpl, "impl address mismatch");
        assertTrue(script.lastImplAddress() != address(0), "impl address is zero");

        // Verify RWAUSD_VERSION is actually consumed: a different version produces a different address
        assertTrue(
            script.lastImplAddress() != script.computeImplAddress("2.0.0"), "version tag not affecting impl address"
        );
    }

    // ============================================================
    // Before state
    // ============================================================

    function test__beforeRunningScript() public view {
        address currentImpl = _getImplementation(PROXY);
        assertTrue(currentImpl != address(0), "no implementation set on proxy");
        assertTrue(
            rwaUSD(PROXY).hasRole(rwaUSD(PROXY).UPGRADER_ROLE(), UPGRADER), "upgrader does not have UPGRADER_ROLE"
        );
    }

    // ============================================================
    // After execution
    // ============================================================

    function test__afterRunningScript() public {
        address oldImpl = _getImplementation(PROXY);

        _upgradeContract();

        address newImpl = _getImplementation(PROXY);
        assertTrue(newImpl != oldImpl, "implementation did not change after upgrade");

        assertEq(rwaUSD(PROXY).name(), "Real World Asset USD", "name changed after upgrade");
        assertEq(rwaUSD(PROXY).symbol(), "rwaUSD", "symbol changed after upgrade");
        assertEq(rwaUSD(PROXY).decimals(), 18, "decimals changed after upgrade");
        assertTrue(rwaUSD(PROXY).hasRole(rwaUSD(PROXY).UPGRADER_ROLE(), UPGRADER), "UPGRADER_ROLE lost after upgrade");
        assertTrue(
            rwaUSD(PROXY).hasRole(rwaUSD(PROXY).DEFAULT_ADMIN_ROLE(), UPGRADER), "DEFAULT_ADMIN_ROLE lost after upgrade"
        );
    }

    // ============================================================
    // Approve while paused
    // ============================================================

    function test_Approve_ZeroValue_RevertsWhenPaused_BeforeUpgrade() public {
        _setupInitialState();

        vm.prank(pauser);
        rwaUSD(PROXY).pause();

        vm.expectRevert();
        vm.prank(alice);
        rwaUSD(PROXY).approve(spender, 0);
    }

    // ============================================================
    // supportsInterface
    // ============================================================

    function test_supportsInterface_BeforeUpgrade() public view {
        assertTrue(rwaUSD(PROXY).supportsInterface(type(IERC20).interfaceId), "IERC20 not supported");
        assertTrue(rwaUSD(PROXY).supportsInterface(type(IBurnMintERC20).interfaceId), "IBurnMintERC20 not supported");
        assertTrue(rwaUSD(PROXY).supportsInterface(type(IGetCCIPAdmin).interfaceId), "IGetCCIPAdmin not supported");
        assertTrue(
            rwaUSD(PROXY).supportsInterface(type(IERC1822Proxiable).interfaceId), "IERC1822Proxiable not supported"
        );
        assertTrue(rwaUSD(PROXY).supportsInterface(type(IAccessControl).interfaceId), "IAccessControl not supported");
        assertTrue(rwaUSD(PROXY).supportsInterface(type(IERC165).interfaceId), "IERC165 not supported");
        assertFalse(
            rwaUSD(PROXY).supportsInterface(type(IAccessControlDefaultAdminRules).interfaceId),
            "IAccessControlDefaultAdminRules should not be supported before upgrade"
        );
    }

    function test_supportsInterface_AfterUpgrade() public {
        _upgradeContract();

        assertTrue(rwaUSD(PROXY).supportsInterface(type(IERC20).interfaceId), "IERC20 not supported");
        assertTrue(rwaUSD(PROXY).supportsInterface(type(IBurnMintERC20).interfaceId), "IBurnMintERC20 not supported");
        assertTrue(rwaUSD(PROXY).supportsInterface(type(IGetCCIPAdmin).interfaceId), "IGetCCIPAdmin not supported");
        assertTrue(
            rwaUSD(PROXY).supportsInterface(type(IERC1822Proxiable).interfaceId), "IERC1822Proxiable not supported"
        );
        assertTrue(rwaUSD(PROXY).supportsInterface(type(IAccessControl).interfaceId), "IAccessControl not supported");
        assertTrue(rwaUSD(PROXY).supportsInterface(type(IERC165).interfaceId), "IERC165 not supported");
        assertFalse(
            rwaUSD(PROXY).supportsInterface(type(IAccessControlDefaultAdminRules).interfaceId),
            "IAccessControlDefaultAdminRules not supported by rwaUSD"
        );
    }

    // ============================================================
    // Complete state preservation
    // ============================================================

    function test_completeStatePreservation_AfterUpgrade() public {
        _setupInitialState();

        TokenState memory before = _captureState(alice);
        _upgradeContract();
        TokenState memory after_ = _captureState(alice);

        _verifyStatePreservation(before, after_);
    }

    function _verifyStatePreservation(TokenState memory before, TokenState memory after_) internal pure {
        assertEq(after_.name, before.name, "name changed");
        assertEq(after_.symbol, before.symbol, "symbol changed");
        assertEq(after_.decimals, before.decimals, "decimals changed");
        assertEq(after_.totalSupply, before.totalSupply, "totalSupply changed");
        assertEq(after_.maxSupply, before.maxSupply, "maxSupply changed");
        assertEq(after_.ccipAdmin, before.ccipAdmin, "ccipAdmin changed");
        assertEq(after_.paused, before.paused, "paused state changed");
        assertEq(after_.userBalance, before.userBalance, "user balance changed");
        assertEq(after_.userAllowanceToSpender, before.userAllowanceToSpender, "allowance changed");
        // Interfaces supported before must still be supported
        assertTrue(after_.supportsIERC20, "lost IERC20");
        assertTrue(after_.supportsIBurnMintERC20, "lost IBurnMintERC20");
        assertTrue(after_.supportsIGetCCIPAdmin, "lost IGetCCIPAdmin");
        assertTrue(after_.supportsIERC1822, "lost IERC1822Proxiable");
        assertTrue(after_.supportsIERC165, "lost IERC165");
        assertTrue(after_.supportsIAccessControl, "lost IAccessControl");
        assertEq(
            after_.supportsIAccessControlDefaultAdminRules,
            before.supportsIAccessControlDefaultAdminRules,
            "IAccessControlDefaultAdminRules support changed"
        );
    }

    // ============================================================
    // Write operation behavior consistency
    // ============================================================

    function _verifyIdenticalBehavior(
        TokenState memory beforeOp,
        TokenState memory afterOp,
        TokenState memory beforeOpUpgraded,
        TokenState memory afterOpUpgraded,
        string memory opName
    ) internal pure {
        int256 supplyChange =
            int256(afterOp.totalSupply) - int256(beforeOp.totalSupply);
        int256 balanceChange = int256(afterOp.userBalance) - int256(beforeOp.userBalance);
        int256 supplyChangeUpgraded = int256(afterOpUpgraded.totalSupply) - int256(beforeOpUpgraded.totalSupply);
        int256 balanceChangeUpgraded = int256(afterOpUpgraded.userBalance) - int256(beforeOpUpgraded.userBalance);

        assertEq(supplyChangeUpgraded, supplyChange, string.concat(opName, ": totalSupply change differs"));
        assertEq(balanceChangeUpgraded, balanceChange, string.concat(opName, ": user balance change differs"));
        assertEq(afterOp.ccipAdmin, afterOpUpgraded.ccipAdmin, string.concat(opName, ": ccipAdmin differs"));
        assertEq(afterOp.paused, afterOpUpgraded.paused, string.concat(opName, ": paused state differs"));
        assertEq(
            afterOp.userAllowanceToSpender,
            afterOpUpgraded.userAllowanceToSpender,
            string.concat(opName, ": allowance differs")
        );
    }

    function test_transfer_BehaviorConsistency_AfterUpgrade() public {
        _setupInitialState();

        TokenState memory before = _captureState(alice);
        vm.prank(alice);
        rwaUSD(PROXY).transfer(bob, TEST_AMOUNT);
        TokenState memory after_ = _captureState(alice);

        _upgradeContract();
        _restoreInitialState();

        TokenState memory beforeUpgraded = _captureState(alice);
        vm.prank(alice);
        rwaUSD(PROXY).transfer(bob, TEST_AMOUNT);
        TokenState memory afterUpgraded = _captureState(alice);

        _verifyIdenticalBehavior(before, after_, beforeUpgraded, afterUpgraded, "transfer");
    }

    function test_approve_BehaviorConsistency_AfterUpgrade() public {
        _setupInitialState();

        TokenState memory before = _captureState(alice);
        vm.prank(alice);
        rwaUSD(PROXY).approve(spender, TEST_AMOUNT * 2);
        TokenState memory after_ = _captureState(alice);

        _upgradeContract();
        _restoreInitialState();

        TokenState memory beforeUpgraded = _captureState(alice);
        vm.prank(alice);
        rwaUSD(PROXY).approve(spender, TEST_AMOUNT * 2);
        TokenState memory afterUpgraded = _captureState(alice);

        _verifyIdenticalBehavior(before, after_, beforeUpgraded, afterUpgraded, "approve");
    }

    function test_transferFrom_BehaviorConsistency_AfterUpgrade() public {
        _setupInitialState();

        // spender already has TEST_AMOUNT allowance from setUp
        TokenState memory before = _captureState(alice);
        vm.prank(spender);
        rwaUSD(PROXY).transferFrom(alice, bob, TEST_AMOUNT / 2);
        TokenState memory after_ = _captureState(alice);

        _upgradeContract();
        _restoreInitialState();

        TokenState memory beforeUpgraded = _captureState(alice);
        vm.prank(spender);
        rwaUSD(PROXY).transferFrom(alice, bob, TEST_AMOUNT / 2);
        TokenState memory afterUpgraded = _captureState(alice);

        _verifyIdenticalBehavior(before, after_, beforeUpgraded, afterUpgraded, "transferFrom");
    }

    function test_mint_BehaviorConsistency_AfterUpgrade() public {
        _setupInitialState();

        TokenState memory before = _captureState(alice);
        vm.prank(minter);
        rwaUSD(PROXY).mint(alice, TEST_AMOUNT);
        TokenState memory after_ = _captureState(alice);

        _upgradeContract();
        _restoreInitialState();

        TokenState memory beforeUpgraded = _captureState(alice);
        vm.prank(minter);
        rwaUSD(PROXY).mint(alice, TEST_AMOUNT);
        TokenState memory afterUpgraded = _captureState(alice);

        _verifyIdenticalBehavior(before, after_, beforeUpgraded, afterUpgraded, "mint");
    }

    function test_burn_BehaviorConsistency_AfterUpgrade() public {
        _setupInitialState();

        vm.prank(UPGRADER);
        rwaUSD(PROXY).grantRole(BURNER_ROLE, alice);

        uint256 burnSnapshot = vm.snapshot();

        TokenState memory before = _captureState(alice);
        vm.prank(alice);
        rwaUSD(PROXY).burn(TEST_AMOUNT);
        TokenState memory after_ = _captureState(alice);

        _upgradeContract();
        vm.revertTo(burnSnapshot);

        vm.prank(UPGRADER);
        rwaUSD(PROXY).grantRole(BURNER_ROLE, alice);

        TokenState memory beforeUpgraded = _captureState(alice);
        vm.prank(alice);
        rwaUSD(PROXY).burn(TEST_AMOUNT);
        TokenState memory afterUpgraded = _captureState(alice);

        _verifyIdenticalBehavior(before, after_, beforeUpgraded, afterUpgraded, "burn");
    }

    function test_burnFrom_BehaviorConsistency_AfterUpgrade() public {
        _setupInitialState();

        vm.prank(UPGRADER);
        rwaUSD(PROXY).grantRole(BURNER_ROLE, burner);

        vm.prank(alice);
        rwaUSD(PROXY).approve(burner, TEST_AMOUNT);

        uint256 burnFromSnapshot = vm.snapshot();

        TokenState memory before = _captureState(alice);
        vm.prank(burner);
        rwaUSD(PROXY).burnFrom(alice, TEST_AMOUNT / 2);
        TokenState memory after_ = _captureState(alice);

        _upgradeContract();
        vm.revertTo(burnFromSnapshot);

        vm.prank(UPGRADER);
        rwaUSD(PROXY).grantRole(BURNER_ROLE, burner);

        TokenState memory beforeUpgraded = _captureState(alice);
        vm.prank(burner);
        rwaUSD(PROXY).burnFrom(alice, TEST_AMOUNT / 2);
        TokenState memory afterUpgraded = _captureState(alice);

        _verifyIdenticalBehavior(before, after_, beforeUpgraded, afterUpgraded, "burnFrom");
    }

    function test_pause_BehaviorConsistency_AfterUpgrade() public {
        _setupInitialState();

        TokenState memory before = _captureState(alice);
        vm.prank(pauser);
        rwaUSD(PROXY).pause();
        TokenState memory after_ = _captureState(alice);

        _upgradeContract();
        _restoreInitialState();

        TokenState memory beforeUpgraded = _captureState(alice);
        vm.prank(pauser);
        rwaUSD(PROXY).pause();
        TokenState memory afterUpgraded = _captureState(alice);

        _verifyIdenticalBehavior(before, after_, beforeUpgraded, afterUpgraded, "pause");
        assertTrue(after_.paused, "should be paused");
        assertTrue(afterUpgraded.paused, "should be paused (upgraded)");
    }
}

